/**
 * Phase 4 Hybrid runner feature flag (default OFF).
 *
 * Reads `chrome.storage.local[HYBRID_NETWORK_CACHE_FEATURE_FLAG_KEY]`. The flag is
 * operator-controlled; when missing or not strictly `true`, the modal runner stays
 * the default. The reader is non-throwing: if `chrome.storage.local` is unavailable
 * (tests, service-worker without permission, etc.) the flag is treated as OFF.
 */
async function readHybridNetworkCacheModeStorageFlag(): Promise<boolean> {
  try {
    const chromeApi = (globalThis as { chrome?: { storage?: { local?: { get?: (key: string) => Promise<Record<string, unknown>> } } } }).chrome;
    const get = chromeApi?.storage?.local?.get;
    if (typeof get !== "function") return false;
    const stored = await get.call(chromeApi!.storage!.local!, "hybrid_network_cache_mode");
    return stored?.hybrid_network_cache_mode === true;
  } catch {
    return false;
  }
}

/**
 * Hybrid collect is enabled when the storage flag OR the state diagnostics mirror
 * says so. Popup readiness uses the mirror; preflight must use the same authority
 * so "Cal ready" and controller gates cannot disagree.
 */
export async function resolveHybridNetworkCacheRunnerEnabled(
  runtime: WholeProfileHarvestRuntime,
  state?: WholeProfileHarvestState
): Promise<boolean> {
  void runtime;
  if (state && isHybridNetworkCacheModeEnabledForCollect(state)) return true;
  return readHybridNetworkCacheModeStorageFlag();
}

async function isHybridNetworkCacheRunnerEnabled(
  runtime: WholeProfileHarvestRuntime,
  state?: WholeProfileHarvestState
): Promise<boolean> {
  return resolveHybridNetworkCacheRunnerEnabled(runtime, state);
}
