const SCAN_PROFILE_ENSURE_CONTENT_SCRIPT_TIMEOUT_MS = 30_000;

function timeoutIso(startIso: string, timeoutMs: number): string {
  return new Date(new Date(startIso).getTime() + timeoutMs).toISOString();
}

async function withScanProfileTimeout<T>(operation: Promise<T>, timeoutMs: number, onTimeout: () => unknown): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  try {
    return await Promise.race([
      operation,
      new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(onTimeout()), timeoutMs);
      })
    ]);
  } finally {
    if (timeoutId) clearTimeout(timeoutId);
  }
}

async function withTimeoutRace<T>(operation: Promise<T>, timeoutMs: number, onTimeout: () => unknown): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  try {
    return await Promise.race([
      operation,
      new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(onTimeout()), timeoutMs);
      })
    ]);
  } finally {
    if (timeoutId) clearTimeout(timeoutId);
  }
}

async function withTimeoutFallback<T>(operation: Promise<T>, timeoutMs: number, onTimeout: () => T): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  try {
    return await Promise.race([
      operation,
      new Promise<T>((resolve) => {
        timeoutId = setTimeout(() => resolve(onTimeout()), timeoutMs);
      })
    ]);
  } finally {
    if (timeoutId) clearTimeout(timeoutId);
  }
}

