type ProfileScanFailureContext = {
  scan_rounds?: number | null;
  grid_detected?: boolean | null;
  expected_count_current?: boolean | null;
  missing_expected_count?: number | null;
  partial_scan?: boolean | null;
  stop_reason?: string | null;
  preflight_error?: string | null;
  no_round_reason?: string | null;
};

function profileDomProbeErrorCode22C9I(value: string | null | undefined): WholeProfileHarvestErrorCode {
  switch (value) {
    case "scan_dom_probe_timeout":
    case "scan_dom_probe_handler_missing":
    case "scan_dom_probe_message_failed":
    case "scan_dom_probe_malformed_response":
    case "scan_dom_probe_execute_script_failed":
    case "scan_dom_probe_not_invoked":
      return value;
    default:
      return "scan_dom_probe_message_failed";
  }
}

export function classifyProfileScanFailure(context: ProfileScanFailureContext): { code: WholeProfileHarvestErrorCode; diagnostics: Record<string, unknown> } | null {
  const scanRounds = typeof context.scan_rounds === "number" ? context.scan_rounds : 0;
  const incompleteBeforeNormalization = context.partial_scan === true || (typeof context.missing_expected_count === "number" && context.missing_expected_count > 0);
  const diagnostics = {
    scan_rounds: scanRounds,
    original_scan_error_before_normalization: incompleteBeforeNormalization ? "profile_scan_incomplete" : null,
    normalized_scan_error: null as WholeProfileHarvestErrorCode | null,
    scan_error_normalizer_applied: scanRounds <= 0 && incompleteBeforeNormalization ? "yes" : "no",
    no_round_guard_applied: scanRounds <= 0 ? "yes" : "no",
    scan_no_round_reason: context.no_round_reason ?? null,
    expected_count_current: context.expected_count_current ?? null,
    grid_detected: context.grid_detected ?? null
  };
  if (scanRounds <= 0) {
    if (context.preflight_error === "profile_grid_not_ready_timeout" || context.no_round_reason === "grid_not_ready") return { code: "profile_grid_not_ready_timeout", diagnostics: { ...diagnostics, normalized_scan_error: "profile_grid_not_ready_timeout", scan_no_round_reason: "grid_not_ready" } };
    if (context.no_round_reason === "expected_count_stale") return { code: "profile_expected_count_stale_after_reset", diagnostics: { ...diagnostics, normalized_scan_error: "profile_expected_count_stale_after_reset", scan_no_round_reason: "expected_count_stale" } };
    if (context.preflight_error) return { code: "profile_scan_preflight_failed", diagnostics: { ...diagnostics, normalized_scan_error: "profile_scan_preflight_failed", scan_preflight_error: context.preflight_error } };
    return { code: "profile_scan_no_round_started", diagnostics: { ...diagnostics, normalized_scan_error: "profile_scan_no_round_started", scan_no_round_reason: context.no_round_reason ?? "controller_aborted_before_round" } };
  }
  const incomplete = context.partial_scan === true || (typeof context.missing_expected_count === "number" && context.missing_expected_count > 0);
  if (incomplete && context.grid_detected === true && context.expected_count_current === true && Boolean(context.stop_reason)) {
    return { code: "profile_scan_incomplete", diagnostics: { ...diagnostics, normalized_scan_error: "profile_scan_incomplete" } };
  }
  return null;
}

type SafeBatchMode = "next_3_safe" | "next_5_safe" | "next_10_safe" | "next_20_safe";

function isSafeBatchMode(value: unknown): value is SafeBatchMode {
  return value === "next_3_safe" || value === "next_5_safe" || value === "next_10_safe" || value === "next_20_safe";
}

function safeBatchModeForLimit(limit: number): SafeBatchMode {
  if (limit <= 3) return "next_3_safe";
  if (limit <= 5) return "next_5_safe";
  if (limit <= 10) return "next_10_safe";
  return "next_20_safe";
}

function buildCollectBatchSizeDiagnostics(args: {
  settingsBatchSize: number | null;
  jobBatchLimit: number;
  runnerBatchLimit: number;
  buttonBatchSize: number;
  messageBatchSize: number;
  batchMode: SafeBatchMode;
}): Record<string, unknown> {
  const values = [args.settingsBatchSize, args.jobBatchLimit, args.runnerBatchLimit, args.buttonBatchSize, args.messageBatchSize].filter((value): value is number => typeof value === "number");
  const consistent = values.length > 0 && values.every((value) => value === values[0]);
  const mismatchReason = consistent
    ? null
    : `settings=${args.settingsBatchSize ?? "unknown"};job=${args.jobBatchLimit};runner=${args.runnerBatchLimit};button=${args.buttonBatchSize};message=${args.messageBatchSize}`;
  return {
    trace_collect_settings_batch_size_source: args.settingsBatchSize === null ? "default_runner_batch_limit" : "collection_settings",
    trace_collect_settings_batch_size_value: args.settingsBatchSize ?? args.runnerBatchLimit,
    trace_collect_job_id_batch_size_value: args.jobBatchLimit,
    trace_collect_job_batch_limit: args.jobBatchLimit,
    trace_collect_batch_limit: args.runnerBatchLimit,
    trace_collect_batch_limit_source: "canonical_effective_batch_limit",
    trace_collect_continue_button_batch_size_value: args.buttonBatchSize,
    trace_collect_continue_message_batch_size_value: args.messageBatchSize,
    trace_collect_batch_size_consistent: consistent ? "yes" : "no",
    trace_collect_batch_size_mismatch_reason: mismatchReason,
    trace_collect_batch_mode_for_batch_size: args.batchMode
  };
}

function safeBatchTargetsForMode(mode: SafeBatchMode): {
  dispatchTarget: AllowedScannerRunnerTarget;
  runnerTarget: AllowedScannerRunnerTarget;
  hardLimit: 3 | 10;
} {
  if (mode === "next_3_safe") {
    return {
      dispatchTarget: DEBUG_NEXT3_BATCH_DISPATCH_TARGET,
      runnerTarget: DEBUG_NEXT3_BATCH_RUNNER_TARGET,
      hardLimit: 3
    };
  }
  return {
    dispatchTarget: CANONICAL_BATCH_DISPATCH_TARGET,
    runnerTarget: CANONICAL_BATCH_RUNNER_TARGET,
    hardLimit: 10
  };
}

const PHASE22C4_MAX_RETRY = 2;
const PHASE22C4_ACTIONABLE_STATUSES = new Set(["new", "pending", "retry", "incomplete", "needs_metadata", "failed_recoverable"]);
const PHASE22C4_NON_ACTIONABLE_STATUSES = new Set(["backend_verified", "complete", "already_collected", "duplicate", "skipped", "failed_permanent", "extracted", "saved"]);
const PHASE22C4_COMPLETE_STATUSES = new Set(["backend_verified", "complete", "already_collected", "extracted", "saved"]);
const PHASE22C4_INCOMPLETE_STATUSES = new Set(["incomplete", "needs_metadata"]);
const PHASE22C4_RETRY_STATUSES = new Set(["retry", "failed_recoverable"]);
const PHASE22C4_RECOVERABLE_REASONS = new Set(["modal_open_failed", "modal_navigation_timeout", "extraction_failed", "finalized_metadata_not_ready", "payload_guard_failed", "backend_network_error", "verify_not_found", "secret_debug_leakage_blocked_locally", "posted_missing", "duration_low_confidence", "backend_secret_guard_rejected", "backend_schema_rejected", "capture_inbox_item_not_found_after_flush", "payload_contains_disallowed_field_local"]);

type Phase22C4SelectionDiagnostics = {
  selected_target_count: number;
  selected_aweme_ids: string[];
  skipped_complete_count: number;
  skipped_backend_verified_count: number;
  selected_retry_count: number;
  selected_incomplete_count: number;
  selected_new_count: number;
  no_actionable_targets: boolean;
};

export type Phase22C4ActionableSelection = {
  targets: WholeProfileHarvestQueueItem[];
  diagnostics: Phase22C4SelectionDiagnostics;
};

function phase22C4RetryCount(item: WholeProfileHarvestQueueItem): number {
  return typeof item.retry_count === "number" ? item.retry_count : item.attempts ?? 0;
}

function phase22C4IsCompleteStatus(status: string, captureStatus?: string): boolean {
  return PHASE22C4_COMPLETE_STATUSES.has(status) || captureStatus === "complete" || captureStatus === "skipped";
}

function phase22C4IsActionableTarget(item: WholeProfileHarvestQueueItem, maxRetry = PHASE22C4_MAX_RETRY): boolean {
  const status = String(item.status);
  if (PHASE22C4_NON_ACTIONABLE_STATUSES.has(status) || phase22C4IsCompleteStatus(status, String(item.capture_status))) return false;
  if (PHASE22C4_RETRY_STATUSES.has(status)) return phase22C4RetryCount(item) < maxRetry;
  return PHASE22C4_ACTIONABLE_STATUSES.has(status) || item.capture_status === "new" || item.capture_status === "incomplete" || item.capture_status === "failed";
}

function isHybridMetricsMissSkippedItem(item: WholeProfileHarvestQueueItem): boolean {
  if (String(item.status) !== "skipped") return false;
  if (item.last_error === "missing_hybrid_metrics") return true;
  const evidence = item.profile_card_evidence;
  return evidence?.hybrid_uncollectable === true;
}

/** Reopen metrics-miss skips so batch-2 retry can hydrate and write instead of pre_skip_failed. */
export function reopenHybridMetricsMissSkippedForCollect(
  state: WholeProfileHarvestState,
  at: string
): { state: WholeProfileHarvestState; reopened_aweme_ids: string[] } {
  const reopenedAwemeIds: string[] = [];
  const queue = state.harvest.queue.map((item): WholeProfileHarvestQueueItem => {
    if (!isHybridMetricsMissSkippedItem(item)) return item;
    reopenedAwemeIds.push(item.aweme_id);
    return {
      ...item,
      status: "needs_metadata",
      capture_status: "incomplete",
      last_error: null,
      extraction_result: null,
      profile_card_evidence: {
        ...item.profile_card_evidence,
        hybrid_uncollectable: false,
        hybrid_uncollectable_reason: null,
        hybrid_reopened_at: at,
        hybrid_reopened_reason: "metrics_miss_collect_retry"
      }
    };
  });
  if (reopenedAwemeIds.length === 0) return { state, reopened_aweme_ids: [] };
  const pending = queue.filter((item) => phase22C4IsActionableTarget(item)).length;
  const snap = state.post_scan_counter_snapshot;
  const restoredSnapshot = snap?.status === "applied"
    ? {
        ...snap,
        new: snap.new + reopenedAwemeIds.length,
        queue: snap.queue + reopenedAwemeIds.length,
        applied_at: at
      }
    : snap;
  return {
    state: refreshHarvestPreview({
      ...state,
      harvest: {
        ...state.harvest,
        queue,
        queue_preview: buildCollectQueuePreviewFromQueue(queue, state.profile_scan.target_details),
        pending,
        updated_at: at
      },
      post_scan_counter_snapshot: restoredSnapshot,
      debug: {
        ...state.debug,
        last_response_summary: {
          ...(state.debug.last_response_summary && typeof state.debug.last_response_summary === "object"
            ? state.debug.last_response_summary as Record<string, unknown>
            : {}),
          hybrid_metrics_miss_reopened_count: reopenedAwemeIds.length
        }
      },
      updated_at: at
    }),
    reopened_aweme_ids: reopenedAwemeIds
  };
}

async function persistReopenedHybridMetricsSkippedToRepository(
  state: WholeProfileHarvestState,
  awemeIds: string[],
  at: string
): Promise<void> {
  const profileUrl = state.profile_url ?? state.source_url ?? null;
  if (!profileUrl || awemeIds.length === 0) return;
  const profileIdentifier = profileIdentifierFromUrl(profileUrl);
  const repository = createProfileTargetRepository();
  for (const awemeId of awemeIds) {
    await repository.updateTargetStatus(profileIdentifier, awemeId, {
      status: "needs_metadata",
      updated_at: at
    }).catch(() => undefined);
  }
}

async function ensureHybridMetricsMissReopenedAtCollectStart(
  runtime: WholeProfileHarvestRuntime,
  state: WholeProfileHarvestState,
  backendCollectRemaining: number,
  at: string
): Promise<WholeProfileHarvestState> {
  if (backendCollectRemaining <= 0) return state;
  if (!state.harvest.queue.some(isHybridMetricsMissSkippedItem)) return state;
  const reopened = reopenHybridMetricsMissSkippedForCollect(state, at);
  if (reopened.reopened_aweme_ids.length === 0) return state;
  let next = reopened.state;
  await persistReopenedHybridMetricsSkippedToRepository(next, reopened.reopened_aweme_ids, at);
  await writeWholeProfileHarvestState(runtime.storage, next);
  return next;
}

async function recoverZeroActionableHybridCollectQueue(
  runtime: WholeProfileHarvestRuntime,
  state: WholeProfileHarvestState,
  backendCollectRemaining: number,
  at: string
): Promise<WholeProfileHarvestState> {
  if (backendCollectRemaining <= 0 || harvestQueueActionableCount(state) > 0) return state;
  if (isHybridTailGapCollect(backendCollectRemaining)) {
    const recovery = await runTailGapCollectQueueRecovery(runtime, state, backendCollectRemaining, at);
    if (recovery.discoveredIds.length > 0) return recovery.state;
  }
  const reopened = reopenHybridMetricsMissSkippedForCollect(state, at);
  let next = reopened.state;
  if (reopened.reopened_aweme_ids.length > 0) {
    await persistReopenedHybridMetricsSkippedToRepository(next, reopened.reopened_aweme_ids, at);
  }
  if (harvestQueueActionableCount(next) > 0) return next;
  const rebuildCap = Math.min(HYBRID_NETWORK_CACHE_MAX_BATCH_SIZE, backendCollectRemaining);
  next = await rebuildHybridCollectQueueFromBackendAuthority(runtime, next, rebuildCap, at);
  return next;
}

export function selectNextActionableTargets(queue: WholeProfileHarvestQueueItem[], limit = 10, mode: WholeProfileHarvestMode = "new_and_incomplete", maxRetry = PHASE22C4_MAX_RETRY): Phase22C4ActionableSelection {
  // Honor the caller limit. Modal Start Collecting passes <=10; Hybrid pre-skip
  // passes up to HYBRID_NETWORK_CACHE_MAX_BATCH_SIZE so one click can drain every
  // already-on-backend item before selecting the write batch. Silently clamping
  // to 10 made pre-skip only clear the first window and look like "backend dead".
  const cappedLimit = Math.max(0, limit);
  const skippedCompleteCount = queue.filter((item) => {
    const status = String(item.status);
    return !["saved", "backend_verified", "already_collected", "extracted"].includes(status) && phase22C4IsCompleteStatus(status, String(item.capture_status));
  }).length;
  const skippedBackendVerifiedCount = queue.filter((item) => String(item.status) === "backend_verified").length;
  const allowed = queue.filter((item) => phase22C4IsActionableTarget(item, maxRetry) && (mode !== "new_only" || ["new", "pending"].includes(String(item.status)) || item.capture_status === "new"));
  const rank = (item: WholeProfileHarvestQueueItem): number => {
    const status = String(item.status);
    if (status === "retry" && phase22C4RetryCount(item) < maxRetry) return 0;
    if (PHASE22C4_INCOMPLETE_STATUSES.has(status) || item.capture_status === "incomplete") return 1;
    if (status === "new" || status === "pending" || item.capture_status === "new" || item.capture_status === "unknown") return 2;
    if (status === "failed_recoverable" && phase22C4RetryCount(item) < maxRetry) return 3;
    return 9;
  };
  const targets = [...allowed].sort((left, right) => rank(left) - rank(right) || left.index - right.index).slice(0, cappedLimit);
  return {
    targets,
    diagnostics: {
      selected_target_count: targets.length,
      selected_aweme_ids: targets.map((item) => item.aweme_id),
      skipped_complete_count: skippedCompleteCount,
      skipped_backend_verified_count: skippedBackendVerifiedCount,
      selected_retry_count: targets.filter((item) => PHASE22C4_RETRY_STATUSES.has(String(item.status))).length,
      selected_incomplete_count: targets.filter((item) => PHASE22C4_INCOMPLETE_STATUSES.has(String(item.status)) || item.capture_status === "incomplete").length,
      selected_new_count: targets.filter((item) => ["new", "pending"].includes(String(item.status)) || item.capture_status === "new" || item.capture_status === "unknown").length,
      no_actionable_targets: targets.length === 0
    }
  };
}

function phase22C4ActionableRemainingCount(queue: WholeProfileHarvestQueueItem[]): number {
  return queue.filter((item) => phase22C4IsActionableTarget(item)).length;
}

