export function isAllowedScannerRunnerTarget(target: unknown): target is AllowedScannerRunnerTarget {
  return typeof target === "string" && ALLOWED_SCANNER_RUNNER_TARGETS.has(target as AllowedScannerRunnerTarget);
}

function isForbiddenScannerRunnerTarget(target: unknown): target is string {
  return typeof target === "string" && FORBIDDEN_SCANNER_RUNNER_TARGETS.has(target);
}

export function assertAllowedScannerRunnerTarget(target: unknown): asserts target is AllowedScannerRunnerTarget {
  if (!isAllowedScannerRunnerTarget(target)) {
    throw new Error(`Forbidden scanner runner target: ${typeof target === "string" ? target : String(target)}`);
  }
}

