export type WholeProfileHarvestRuntime = WholeProfileScannerTransport & WholeProfileDryRunTransport & {
  storage: WholeProfileHarvestStorage;
  runPostPingProfileDomProbe22C9I?(context: { scanRunId: string; tabId: number; tabUrl: string | null; traceVersion: "22C-9I" | "22C-9K" | "22C-9M" | "22C-9Z-NOGIT" | "22C-9Z-3" | "22C-9Z-4C" | "22C-9Z-9" | "22C-12F" }): Promise<WholeProfileDomProbe22C9IResult>;
  getExtractionContext?(tabId: number): Promise<{ current_url: string | null; page_type: string | null; modal_id: string | null; modal_id_present?: boolean; metric_rail_visible?: boolean; diagnostics?: Record<string, unknown> }>;
  getActiveTab(): Promise<{ id?: number; url?: string | null }>;
  /** Prefer a Douyin tab that matches the profile being collected. */
  resolveDouyinTabForProfile?(profileUrl: string): Promise<{ id?: number; url?: string | null }>;
  /** Open or navigate a Douyin tab to the profile URL for tail-gap profile-post discovery. */
  ensureDouyinTabForProfile?(profileUrl: string): Promise<{ id: number; url: string | null; navigated: boolean; created: boolean }>;
  /** DOM grid tail-reconcile probe (same source as scan final-gap recovery). */
  readDomTailReconcileProbeFromTab?(tabId: number, profileUrl: string, options?: { forceDomScroll?: boolean; allowCappedDomScroll?: boolean }): Promise<Record<string, unknown>>;
  ensureContentScriptReady(tabId: number): Promise<{ ok: boolean; status: string; detector_status?: string | null; page_type?: string | null; current_url?: string | null; modal_id?: string | null; error?: string | null; diagnostics?: Record<string, unknown> }>;
  getActualProfileReadiness?(tabId: number, expectedProfileUrl: string): Promise<WholeProfileActualProfileReadiness>;
  refreshDouyinTabContextAfterNavigation?(tabId: number, cleanProfileUrl: string): Promise<WholeProfileActualProfileReadiness>;
  closeDouyinModalIfPresent?(tabId: number, cleanProfileUrl: string): Promise<{ ok: boolean; attempted: boolean; strategy: string | null; modal_still_visible: boolean; current_url: string | null; page_type: string | null; diagnostics: Record<string, unknown> }>;
  getCalibration(): Promise<unknown>;
  ensureProfilePageFromModal?(tabId: number, profileUrl: string, sourceModalAwemeId: string): Promise<WholeProfileModalTransitionResult>;
  closeModalToProfile?(tabId: number, profileUrl: string, sourceModalAwemeId: string): Promise<WholeProfileModalTransitionResult>;
  waitForProfileReady?(tabId: number, profileUrl: string): Promise<WholeProfileProfileReadyResult>;
  navigateToProfile?(tabId: number, profileUrl: string): Promise<void>;
  createCanonicalHarvestSession?(request: ReturnType<typeof buildCanonicalHarvestSessionRequest>): Promise<WholeProfileCaptureSessionResult>;
  listCaptureSessions?(): Promise<WholeProfileCaptureSessionListResult>;
  listCaptureInboxProfileItems?(profileUrl: string): Promise<WholeProfileCaptureInboxProfileItemsResult>;
  listCaptureInboxProfileSummary?(profileUrl: string): Promise<WholeProfileCaptureInboxProfileSummaryResult>;
  getBackendBaseUrl?(): string | null;
  classifyTargets?(request: WholeProfileTargetClassificationRequest): Promise<WholeProfileTargetClassificationResponse>;
  classifyProfileVideos?(request: DouyinProfileVideoClassificationRequest): Promise<DouyinProfileVideoClassificationResponse>;
  detectCaptchaOrCheckpoint?(tabId: number): Promise<WholeProfileCaptchaCheck>;
  checkDouyinTabContext?(tabId: number): Promise<DouyinTabContextCheck>;
  openTargetModalWithTimeout?(tabId: number, targetUrl: string, awemeId: string, options?: { urlTimeoutMs?: number; domTimeoutMs?: number; metadataTimeoutMs?: number; retryOnce?: boolean }): Promise<OpenTargetModalSchedulerResult>;
  flushCanonicalHarvestPayload?(payload: CanonicalHarvestPayload | FullModalHarvestRequestPayload, headers: Record<string, string>): Promise<WholeProfileBackendFlushResult>;
  listCaptureSessionItems?(captureSessionId: string): Promise<WholeProfileCaptureSessionItemsResult>;
  sleep?(ms: number): Promise<void>;
  now?: () => string;
  random?: () => number;
  /** Phase 4.4c: Read window.__REUP_DOUYIN_NETWORK_CACHE__ from the active Douyin tab. */
  readNetworkCacheFromTab?(tabId: number): Promise<unknown[]>;
  /** Phase 4.4c: Read passive network probe diagnostics (runtime authority snapshot) from the active tab's content script. */
  readPassiveProbeDiagnosticsFromTab?(tabId: number): Promise<Record<string, unknown>>;
  /**
   * Part B: actively fetch real per-video detail evidence for tail targets whose
   * metrics were evicted from the in-tab caches. Runs a tab-scoped fetch of each
   * video page and returns parsed NetworkVideoMetadata (with real statistics).
   */
  hydrateDetailEvidenceFromTab?(tabId: number, discoveries: Array<{ aweme_id: string; source_url: string }>): Promise<NetworkVideoMetadata[]>;
  /** Phase C: paginate aweme/post in the profile tab to recover tail metrics. */
  fetchProfilePostPageFromTab?(
    tabId: number,
    profileUrl: string,
    cursor: string | number | null,
    pageIndex: number
  ): Promise<ProfilePostPageFetchResponse>;
};

function mergeCalibrationDiagnostics(details: Record<string, unknown> | null | undefined, patch: Record<string, unknown>): Record<string, unknown> {
  return {
    ...(details && typeof details === "object" ? details : {}),
    ...patch
  };
}

function extractCanonicalCalibrationCandidate(stored: Record<string, unknown>): WholeProfileHarvestState["calibration"] | null {
  const canonical = stored[DOUYIN_SCANNER_CALIBRATION_KEY];
  if (canonical && typeof canonical === "object") return createWholeProfileHarvestCalibration(normalizeDouyinCalibration(canonical, { source: "canonical" }));
  const bridge = stored[DOUYIN_SCANNER_STORAGE_ROOT_KEY];
  if (bridge && typeof bridge === "object") {
    const calibration = (bridge as { calibration?: unknown }).calibration;
    if (calibration && typeof calibration === "object") return createWholeProfileHarvestCalibration(normalizeDouyinCalibration(calibration, { source: "canonical" }));
  }
  return null;
}

function withPreservedCalibration(state: WholeProfileHarvestState, fallback: WholeProfileHarvestState["calibration"], source: "state" | "canonical_storage"): WholeProfileHarvestState {
  const chosen = chooseMoreCompleteCalibration(state.calibration, fallback);
  const preserved = calibrationFingerprint(chosen) !== calibrationFingerprint(state.calibration);
  return {
    ...state,
    calibration: chosen,
    debug: {
      ...state.debug,
      last_request_summary: mergeCalibrationDiagnostics(state.debug.last_request_summary as Record<string, unknown> | null | undefined, {
        calibration_preserved: preserved,
        calibration_preserved_source: source,
        calibration_ready_after_write: chosen.ready === true && chosen.status === "calibrated",
        calibration_point_count_after_write: chosen.point_count
      })
    }
  };
}

export async function readWholeProfileHarvestState(storage: WholeProfileHarvestStorage, now: string | null = null): Promise<WholeProfileHarvestState> {
  const stored = {
    ...(await storage.get(WHOLE_PROFILE_HARVEST_STATE_KEY)),
    ...(await storage.get(DOUYIN_SCANNER_CALIBRATION_KEY)),
    ...(await storage.get(DOUYIN_SCANNER_STORAGE_ROOT_KEY))
  };
  const at = now ?? new Date().toISOString();
  const normalized = migrateLegacyScannerStateToCanonical(normalizeWholeProfileHarvestState(stored[WHOLE_PROFILE_HARVEST_STATE_KEY], at), at);
  const readTimeMs = Date.parse(at);
  const lockExpiredAtReadTime = persistentCollectJobLockExpired(normalized.collect_job, Number.isFinite(readTimeMs) ? readTimeMs : Date.now());
  const lockExpiryContradiction = normalized.collect_job.lock_released === true && lockExpiredAtReadTime === false;
  const normalizedWithReadTimeLockDiagnostics = {
    ...normalized,
    debug: {
      ...normalized.debug,
      last_request_summary: {
        ...(normalized.debug.last_request_summary && typeof normalized.debug.last_request_summary === "object" ? normalized.debug.last_request_summary as Record<string, unknown> : {}),
        trace_collect_lock_expired_recomputed_on_read: lockExpiredAtReadTime ? "yes" : "no",
        trace_collect_lock_expired_read_time_source: "Date.now_minus_lock_expires_at",
        trace_collect_lock_released_expiry_contradiction: lockExpiryContradiction ? "yes" : "no",
        trace_collect_lock_released_expiry_contradiction_reason: lockExpiryContradiction ? "lock_marked_released_before_expiry_at_read_time" : null
      }
    }
  };
  const canonical = extractCanonicalCalibrationCandidate(stored);
  if (!canonical) return normalizedWithReadTimeLockDiagnostics;
  const chosen = chooseMoreCompleteCalibration(normalizedWithReadTimeLockDiagnostics.calibration, canonical);
  const hydrated = calibrationFingerprint(chosen) !== calibrationFingerprint(normalizedWithReadTimeLockDiagnostics.calibration);
  return hydrated
    ? {
        ...normalizedWithReadTimeLockDiagnostics,
        calibration: chosen,
        debug: {
          ...normalizedWithReadTimeLockDiagnostics.debug,
          last_request_summary: mergeCalibrationDiagnostics(normalizedWithReadTimeLockDiagnostics.debug.last_request_summary as Record<string, unknown> | null | undefined, {
            calibration_hydrated_from_storage: true,
            calibration_hydrated_source: "canonical_storage",
            calibration_ready_after_hydration: chosen.ready === true && chosen.status === "calibrated",
            calibration_point_count_after_hydration: chosen.point_count
          })
        }
      }
    : normalizedWithReadTimeLockDiagnostics;
}

// Collect-job lifecycle sets used by the stale-write rejection guard below.
// ACTIVE = job is in-flight; TERMINAL = job has finished. A write that would
// move the SAME job from TERMINAL back to ACTIVE is, by definition, a stale
// snapshot from before completion and must never be allowed to land.
const GUARD_ACTIVE_COLLECT_JOB_STATES: ReadonlySet<string> = new Set([
  "starting",
  "running",
  "running_tab_inactive",
  "waiting_for_active_tab",
  "paused_tab_inactive",
  "recovering"
]);
const GUARD_TERMINAL_COLLECT_JOB_STATES: ReadonlySet<string> = new Set([
  "completed",
  "failed",
  "stuck",
  "aborted_by_user_fix_stuck"
]);

/** Independent completion signal written by the Hybrid runner. Survives main-state clobber. */
export const HYBRID_COLLECTION_DONE_KEY = "hybrid_collection_done" as const;

export type HybridCollectionDoneSignal = {
  job_id: string | null;
  runtime_generation: number;
  completed_at: string;
  outcome: string;
  write_ok?: boolean;
  write_ok_count?: number;
  write_fail_count?: number;
  per_item_count?: number;
  verify_ok?: string;
  /** Capture Inbox card tile authority — survives main-state heartbeat clobber. */
  tile_already?: number;
  tile_new?: number;
  tile_queue?: number;
  scanned_total?: number;
};

type CollectJobWriteGuardReason =
  | "stale_runtime_generation"
  | "terminal_collect_job_revert"
  | "hybrid_collection_done_active";

type CollectJobWriteGuardDecision =
  | { reject: false; incomingJobGeneration: number; storedJobGeneration: number }
  | { reject: true; reason: CollectJobWriteGuardReason; incomingJobGeneration: number; storedJobGeneration: number };

/**
 * Pure guard decision for collect-job writes. Exported for unit tests.
 *
 * Rejects:
 *  1. Older runtime_generation for the same job_id
 *  2. Active-state write that would revert a terminal job of the same job_id
 *  3. Active-state write for a job already marked done in hybrid_collection_done
 *     (defense-in-depth when main state was clobbered but the done key survived)
 */
export function evaluateCollectJobWriteGuard(
  stored: WholeProfileHarvestState,
  incoming: WholeProfileHarvestState,
  doneSignal: HybridCollectionDoneSignal | null = null
): CollectJobWriteGuardDecision {
  const sameCollectJob = stored.collect_job.job_id !== null
    && stored.collect_job.job_id === incoming.collect_job.job_id;
  const incomingJobGeneration = incoming.collect_job.runtime_generation ?? 0;
  const storedJobGeneration = stored.collect_job.runtime_generation ?? 0;
  const legitimateRestart = sameCollectJob && incomingJobGeneration > storedJobGeneration;
  const staleGeneration = sameCollectJob && !legitimateRestart && incomingJobGeneration < storedJobGeneration;
  const terminalReverted = sameCollectJob
    && !legitimateRestart
    && GUARD_TERMINAL_COLLECT_JOB_STATES.has(stored.collect_job.state)
    && GUARD_ACTIVE_COLLECT_JOB_STATES.has(incoming.collect_job.state);
  if (staleGeneration) {
    return { reject: true, reason: "stale_runtime_generation", incomingJobGeneration, storedJobGeneration };
  }
  if (terminalReverted) {
    return { reject: true, reason: "terminal_collect_job_revert", incomingJobGeneration, storedJobGeneration };
  }
  // Defense-in-depth: even if main state was clobbered back to starting, the
  // independent hybrid_collection_done key still proves this job finished.
  // Reject any active write for that job unless it is a legitimate restart
  // (strictly higher collect_job.runtime_generation).
  if (
    doneSignal
    && doneSignal.job_id
    && incoming.collect_job.job_id === doneSignal.job_id
    && GUARD_ACTIVE_COLLECT_JOB_STATES.has(incoming.collect_job.state)
    && incomingJobGeneration <= (doneSignal.runtime_generation ?? 0)
  ) {
    return { reject: true, reason: "hybrid_collection_done_active", incomingJobGeneration, storedJobGeneration };
  }
  return { reject: false, incomingJobGeneration, storedJobGeneration };
}

function nonNegativeIntField(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? Math.round(value) : null;
}

export function parseHybridCollectionDoneSignal(value: unknown): HybridCollectionDoneSignal | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  const jobId = typeof record.job_id === "string" && record.job_id.trim() ? record.job_id.trim() : null;
  const completedAt = typeof record.completed_at === "string" ? record.completed_at : null;
  const outcome = typeof record.outcome === "string" ? record.outcome : null;
  if (!jobId || !completedAt || !outcome) return null;
  const signal: HybridCollectionDoneSignal = {
    job_id: jobId,
    runtime_generation: typeof record.runtime_generation === "number" && Number.isFinite(record.runtime_generation)
      ? record.runtime_generation
      : 0,
    completed_at: completedAt,
    outcome
  };
  if (typeof record.write_ok === "boolean") signal.write_ok = record.write_ok;
  if (typeof record.write_ok_count === "number") signal.write_ok_count = record.write_ok_count;
  if (typeof record.write_fail_count === "number") signal.write_fail_count = record.write_fail_count;
  if (typeof record.per_item_count === "number") signal.per_item_count = record.per_item_count;
  if (typeof record.verify_ok === "string") signal.verify_ok = record.verify_ok;
  const tileAlready = nonNegativeIntField(record.tile_already);
  const tileNew = nonNegativeIntField(record.tile_new);
  const tileQueue = nonNegativeIntField(record.tile_queue);
  const scannedTotal = nonNegativeIntField(record.scanned_total);
  if (tileAlready != null) signal.tile_already = tileAlready;
  if (tileNew != null) signal.tile_new = tileNew;
  if (tileQueue != null) signal.tile_queue = tileQueue;
  if (scannedTotal != null) signal.scanned_total = scannedTotal;
  return signal;
}

function hybridDoneSignalTileFields(state: WholeProfileHarvestState): Pick<HybridCollectionDoneSignal, "tile_already" | "tile_new" | "tile_queue" | "scanned_total"> {
  const summary = state.debug.last_response_summary && typeof state.debug.last_response_summary === "object"
    ? state.debug.last_response_summary as Record<string, unknown>
    : {};
  const postRunAlready = typeof summary.hybrid_runner_post_run_tile_already === "number" && Number.isFinite(summary.hybrid_runner_post_run_tile_already)
    ? Math.max(0, Math.round(summary.hybrid_runner_post_run_tile_already))
    : null;
  const postRunNew = typeof summary.hybrid_runner_post_run_tile_new === "number" && Number.isFinite(summary.hybrid_runner_post_run_tile_new)
    ? Math.max(0, Math.round(summary.hybrid_runner_post_run_tile_new))
    : null;
  const snapshot = state.post_scan_counter_snapshot;
  if (postRunAlready != null && postRunNew != null) {
    const scanned = Math.max(
      snapshot?.scanned_total ?? 0,
      state.scan_job.total_persisted ?? 0,
      postRunAlready + postRunNew
    );
    return {
      tile_already: postRunAlready,
      tile_new: postRunNew,
      tile_queue: postRunNew,
      scanned_total: scanned
    };
  }
  if (!snapshot || snapshot.status !== "applied") return {};
  return {
    tile_already: snapshot.already_collected,
    tile_new: snapshot.new,
    tile_queue: snapshot.queue,
    scanned_total: snapshot.scanned_total
  };
}

/**
 * Prefer the higher applied already_collected for the same profile so a late
 * in-flight heartbeat (snapshot still at pre-run 41) cannot clobber post-run
 * card authority (61).
 */
function preferMonotonicPostScanSnapshot(
  stored: WholeProfileHarvestState["post_scan_counter_snapshot"],
  incoming: WholeProfileHarvestState["post_scan_counter_snapshot"]
): WholeProfileHarvestState["post_scan_counter_snapshot"] {
  if (!incoming) return stored;
  if (!stored || stored.status !== "applied") return incoming;
  if (incoming.status !== "applied") return stored;
  if (
    stored.profile_identifier
    && incoming.profile_identifier
    && stored.profile_identifier !== incoming.profile_identifier
  ) {
    return incoming;
  }
  const downgradeSources = new Set([
    "local_fallback_backend_unavailable",
    "backend_empty_disproves_snapshot"
  ]);
  if (
    incoming.source
    && downgradeSources.has(incoming.source)
    && incoming.already_collected < stored.already_collected
  ) {
    // Post-collect Capture Inbox card authority must not lose to a stale wipe reconcile.
    if (stored.source === "backend_capture_inbox_profile_summary" && stored.already_collected > 0) {
      return stored;
    }
    return incoming;
  }
  if (incoming.already_collected >= stored.already_collected) return incoming;
  return stored;
}

async function readHybridCollectionDoneSignal(storage: WholeProfileHarvestStorage): Promise<HybridCollectionDoneSignal | null> {
  try {
    const raw = await storage.get(HYBRID_COLLECTION_DONE_KEY);
    return parseHybridCollectionDoneSignal((raw as Record<string, unknown>)[HYBRID_COLLECTION_DONE_KEY]);
  } catch {
    return null;
  }
}

function stampStaleWriteRejection(
  stored: WholeProfileHarvestState,
  incoming: WholeProfileHarvestState,
  decision: Extract<CollectJobWriteGuardDecision, { reject: true }>
): WholeProfileHarvestState {
  const rejectedAt = new Date().toISOString();
  return {
    ...stored,
    debug: {
      ...stored.debug,
      last_request_summary: {
        ...(stored.debug.last_request_summary && typeof stored.debug.last_request_summary === "object" ? stored.debug.last_request_summary as Record<string, unknown> : {}),
        trace_stale_state_write_rejected: "yes",
        trace_stale_state_write_rejected_reason: decision.reason,
        trace_stale_state_write_rejected_at: rejectedAt,
        trace_stale_state_write_rejected_job_id: stored.collect_job.job_id,
        trace_stale_state_write_rejected_incoming_job_state: incoming.collect_job.state,
        trace_stale_state_write_rejected_stored_job_state: stored.collect_job.state,
        trace_stale_state_write_rejected_incoming_generation: decision.incomingJobGeneration,
        trace_stale_state_write_rejected_stored_generation: decision.storedJobGeneration
      }
    }
  };
}

export async function writeWholeProfileHarvestState(storage: WholeProfileHarvestStorage, state: WholeProfileHarvestState): Promise<WholeProfileHarvestState> {
  // === STALE-WRITE REJECTION GUARD (collect-job freeze root cause) ===
  // Popup and service worker hold independent in-memory snapshots. A slow writer
  // that captured "starting"/"running" can otherwise clobber a newer completion
  // write (lost-update / TOCTOU). The guard is evaluated against a FRESH read
  // immediately before storage.set so a completion that lands between an earlier
  // read and this set is still protected.
  const doneSignal = await readHybridCollectionDoneSignal(storage);

  // First pass: cheap reject when the caller's snapshot is already known-stale.
  const initialStored = await readWholeProfileHarvestState(storage, state.updated_at ?? null);
  const initialDecision = evaluateCollectJobWriteGuard(initialStored, state, doneSignal);
  if (initialDecision.reject) {
    const guarded = stampStaleWriteRejection(initialStored, state, initialDecision);
    console.warn("[COLLECT_JOB_STATE_GUARD] Rejected stale scanner state write", {
      job_id: initialStored.collect_job.job_id,
      reason: initialDecision.reason,
      stored_job_state: initialStored.collect_job.state,
      incoming_job_state: state.collect_job.state,
      stored_collect_job_generation: initialDecision.storedJobGeneration,
      incoming_collect_job_generation: initialDecision.incomingJobGeneration
    });
    await safeChromeStorageLocalSet({ [WHOLE_PROFILE_HARVEST_STATE_KEY]: guarded });
    return guarded;
  }

  // TOCTOU close: re-read immediately before set and re-evaluate.
  // fix for the pre-skip freeze where popup probe-sync read "starting", the
  // hybrid runner wrote "completed", then probe-sync set the stale starting
  // snapshot and re-locked the UI.
  const freshStored = await readWholeProfileHarvestState(storage, state.updated_at ?? null);
  const freshDoneSignal = await readHybridCollectionDoneSignal(storage);
  const freshDecision = evaluateCollectJobWriteGuard(freshStored, state, freshDoneSignal);
  if (freshDecision.reject) {
    const guarded = stampStaleWriteRejection(freshStored, state, freshDecision);
    console.warn("[COLLECT_JOB_STATE_GUARD] Rejected stale scanner state write (pre-set re-read)", {
      job_id: freshStored.collect_job.job_id,
      reason: freshDecision.reason,
      stored_job_state: freshStored.collect_job.state,
      incoming_job_state: state.collect_job.state,
      stored_collect_job_generation: freshDecision.storedJobGeneration,
      incoming_collect_job_generation: freshDecision.incomingJobGeneration
    });
    await safeChromeStorageLocalSet({ [WHOLE_PROFILE_HARVEST_STATE_KEY]: guarded });
    return guarded;
  }

  const source = calibrationFingerprint(freshStored.calibration) !== calibrationFingerprint(state.calibration) ? "state" : "canonical_storage";
  const calibrated = withPreservedCalibration(state, freshStored.calibration, source);
  const next: WholeProfileHarvestState = refreshHarvestPreview({
    ...calibrated,
    post_scan_counter_snapshot: preferMonotonicPostScanSnapshot(
      freshStored.post_scan_counter_snapshot,
      calibrated.post_scan_counter_snapshot
    )
  });
  const terminalWrite = GUARD_TERMINAL_COLLECT_JOB_STATES.has(next.collect_job.state)
    || next.phase === "blocked"
    || next.phase === "failed"
    || next.phase === "start_failed_recoverable";
  if (isChromeStorageWriteQuotaBlocked() && !terminalWrite) {
    console.warn("[COLLECT_JOB_STATE_GUARD] Storage write quota exceeded; skipping non-terminal state persist.");
    return next;
  }
  try {
    await storage.set({ [WHOLE_PROFILE_HARVEST_STATE_KEY]: next });
  } catch (error) {
    if (isChromeStorageWriteQuotaError(error)) {
      console.warn("[COLLECT_JOB_STATE_GUARD] Storage write quota exceeded; state kept in-memory for this turn.");
      return next;
    }
    throw error;
  }
  if (next.layer.profile_scan_ready && next.profile_scan.status === "success") {
    void touchProfileSessionIndexFromScanState(storage, next, next.updated_at ?? new Date().toISOString()).catch(() => undefined);
  }
  return next;
}

async function writeWholeProfileHarvestStateDirect(storage: WholeProfileHarvestStorage, state: WholeProfileHarvestState): Promise<WholeProfileHarvestState> {
  await storage.set({ [WHOLE_PROFILE_HARVEST_STATE_KEY]: state });
  return state;
}

/**
 * Hybrid loop heartbeat: merge only live progress fields onto a fresh storage
 * read. Never full-replace — a timed-out writeWholeProfileHarvestStateDirect
 * can otherwise land AFTER post-run card refresh and clobber Already from 61
 * back to the pre-run snapshot (production: fossil tile_already=61, UI=41).
 */
export async function writeHybridLoopHeartbeat(
  storage: WholeProfileHarvestStorage,
  heartbeatState: WholeProfileHarvestState
): Promise<WholeProfileHarvestState> {
  const fresh = await readWholeProfileHarvestState(storage, heartbeatState.updated_at ?? null);
  if (
    fresh.harvest.status === "paused"
    || fresh.harvest.paused_reason === "backend_auth_required"
    || fresh.harvest.paused_reason === "douyin_login_required"
  ) {
    return fresh;
  }
  const appAuth = await readAppBackendAuthFromStorage(storage);
  if (!appAuth.loggedIn) {
    return fresh;
  }
  const sameJob = fresh.collect_job.job_id != null
    && fresh.collect_job.job_id === heartbeatState.collect_job.job_id;
  const freshGeneration = fresh.collect_job.runtime_generation ?? 0;
  const heartbeatGeneration = heartbeatState.collect_job.runtime_generation ?? 0;
  if (sameJob && GUARD_TERMINAL_COLLECT_JOB_STATES.has(fresh.collect_job.state) && freshGeneration >= heartbeatGeneration) {
    return fresh;
  }
  const doneSignal = await readHybridCollectionDoneSignal(storage);
  if (
    doneSignal?.job_id
    && heartbeatState.collect_job.job_id === doneSignal.job_id
    && heartbeatGeneration <= (doneSignal.runtime_generation ?? 0)
  ) {
    return fresh;
  }
  // Prefer the larger selected/batch totals from the live runner so UI never
  // shows "Collecting 140 / 10" (stale Next-10 job fields vs hybrid drain of 500).
  const liveSelected = Math.max(
    heartbeatState.collect_job.selected_count ?? 0,
    heartbeatState.collect_job.batch_limit ?? 0,
    heartbeatState.collect_job.attempted_count ?? 0,
    fresh.collect_job.selected_count ?? 0
  );
  const next: WholeProfileHarvestState = {
    ...fresh,
    collect_job: {
      ...fresh.collect_job,
      state: heartbeatState.collect_job.state,
      heartbeat_at: heartbeatState.collect_job.heartbeat_at,
      current_step: heartbeatState.collect_job.current_step,
      current_aweme_id: heartbeatState.collect_job.current_aweme_id,
      current_item_index: heartbeatState.collect_job.current_item_index,
      attempted_count: heartbeatState.collect_job.attempted_count,
      succeeded_count: heartbeatState.collect_job.succeeded_count,
      failed_count: heartbeatState.collect_job.failed_count,
      skipped_count: heartbeatState.collect_job.skipped_count,
      selected_count: liveSelected > 0 ? liveSelected : fresh.collect_job.selected_count,
      batch_limit: liveSelected > 0 ? liveSelected : fresh.collect_job.batch_limit,
      lock_owner: heartbeatState.collect_job.lock_owner,
      lock_expires_at: heartbeatState.collect_job.lock_expires_at,
      lock_released: heartbeatState.collect_job.lock_released,
      updated_at: heartbeatState.collect_job.updated_at
    },
    active_collect_runtime: heartbeatState.active_collect_runtime,
    post_scan_counter_snapshot: preferMonotonicPostScanSnapshot(
      fresh.post_scan_counter_snapshot,
      heartbeatState.post_scan_counter_snapshot
    ),
    updated_at: heartbeatState.updated_at ?? fresh.updated_at
  };
  if (shouldThrottleHybridHeartbeatPersist()) {
    return next;
  }
  markHybridHeartbeatPersisted();
  if (isChromeStorageWriteQuotaBlocked()) {
    return next;
  }
  try {
    await storage.set({ [WHOLE_PROFILE_HARVEST_STATE_KEY]: next });
  } catch (error) {
    if (isChromeStorageWriteQuotaError(error)) {
      return next;
    }
    throw error;
  }
  return next;
}

function setScannerActionDiagnostic(
  state: WholeProfileHarvestState,
  patch: { clicked?: string | null; result?: string | null; error?: string | null; started_at?: string | null; finished_at?: string | null; details?: Record<string, unknown> | null }
): WholeProfileHarvestState {
  return {
    ...state,
    debug: {
      ...state.debug,
      last_action_clicked: Object.prototype.hasOwnProperty.call(patch, "clicked") ? patch.clicked ?? null : state.debug.last_action_clicked,
      last_action_result: Object.prototype.hasOwnProperty.call(patch, "result") ? patch.result ?? null : state.debug.last_action_result,
      last_action_error: Object.prototype.hasOwnProperty.call(patch, "error") ? patch.error ?? null : state.debug.last_action_error,
      last_action_started_at: Object.prototype.hasOwnProperty.call(patch, "started_at") ? patch.started_at ?? null : state.debug.last_action_started_at,
      last_action_finished_at: Object.prototype.hasOwnProperty.call(patch, "finished_at") ? patch.finished_at ?? null : state.debug.last_action_finished_at,
      active_task: state.workflow.active_task,
      busy_source: state.workflow.active_task,
      busy_stale: false,
      last_request_summary: patch.details ? { ...(state.debug.last_request_summary && typeof state.debug.last_request_summary === "object" ? state.debug.last_request_summary as Record<string, unknown> : {}), ...patch.details } : state.debug.last_request_summary
    }
  };
}

function scannerActionError(message: string): WholeProfileHarvestLastError {
  return { code: "scanner_action_blocked", message, failed_count: 0, sample_failed_aweme_ids: [], details: null };
}

type StartCollectingPreflightStage = "queue_exists" | "first_pending_target_exists" | "calibration_ready" | "calibration_context_valid" | "api_base_ready" | "backend_session_verified_or_created" | "modal_detail_url_buildable" | "runner_available";

export type WholeProfileResetMode = "current_run" | "current_profile_rescan" | "new_profile" | "full_local_reset_dev_only";

export type WholeProfileResetOptions = {
  mode?: WholeProfileResetMode;
  detectedProfile?: DouyinProfileIdentity | null;
};

type StartCollectingPreflightResult = {
  ok: boolean;
  blockedReason: string | null;
  stage: StartCollectingPreflightStage;
  details: Record<string, unknown>;
  target: WholeProfileFirstPendingCollectTarget | null;
  captureSessionId: string | null;
  expectedDetailUrl: string | null;
};

function startCollectingDiagnostics(patch: Record<string, unknown>): Record<string, unknown> {
  return {
    last_scanner_action: "start_collecting",
    ...patch
  };
}

