    trace_collect_runner_contract_failed: "no",
    trace_collect_runner_contract_failure_reason: null,
    trace_start_collecting_expected_runner_type: "batch_collect",
    trace_start_collecting_actual_runner_type: "batch_collect",
    trace_start_collecting_route_contract_enforced: "yes",
    trace_start_collecting_route_contract_passed: "yes",
    trace_start_collecting_route_contract_failed: "no",
    trace_start_collecting_route_contract_failed_reason: null,
    trace_start_collecting_legacy_fallback_attempted: "no",
    trace_start_collecting_legacy_fallback_blocked: "yes",
    trace_start_collecting_fail_fast_instead_of_legacy_fallback: "yes",
