    const capturedAwemeIdSetStale = capturedAwemeIdCountActual > 0 && capturedAwemeIdCountActual !== backendCapturedRaw && backendCapturedRaw > 0;
    const capturedAwemeIdSetStaleReason = capturedAwemeIdCountActual < backendCapturedRaw
