  const modalIdPresent = Boolean(ready.modal_id) || urlHasModalId(currentUrl);
  const urlMatchesProfile = urlsMatchWithoutTrailingSlash(currentUrl, profileUrl);
  const pageType = ready.page_type === "profile" || ready.page_type === "modal" || ready.page_type === "video" ? ready.page_type : "unknown";
  const notReady = modalIdPresent || pageType === "modal" ? "still_modal" : !urlMatchesProfile ? "url_not_profile" : !ready.ok ? "content_script_missing" : ready.detector_status !== "ready" ? "detector_failed" : "grid_candidates_missing";
